// Single source for the home view's framing AND the generated SKILL.md (AXI
// principle 7). Edit here; skills/crswd-axi/SKILL.md is regenerated by
// `npm run skill:gen` and CI fails if it drifts (`npm run skill:check`).

import { homedir } from "node:os";
import { emitList } from "../output/toon.js";

export const DESCRIPTION =
  "Drive crswd's signed session API: list, show, create, prompt, output, close";

export const SPEC_VERSION = "axi/1.0-2026-07";

export const COMMANDS: Array<{ command: string; summary: string }> = [
  { command: "list", summary: "Every session, capturing any bearer crswd hands over" },
  { command: "show", summary: "One session in full" },
  { command: "create", summary: "Start a session and record its bearer" },
  { command: "prompt", summary: "Type into a session and submit" },
  { command: "output", summary: "What the session's pane currently shows" },
  { command: "close", summary: "Destroy a session" },
  { command: "doctor", summary: "Probe every connector and name the fix for each gap" },
];

export function collapseHome(path: string): string {
  const home = homedir();
  return path.startsWith(home) ? "~" + path.slice(home.length) : path;
}

export function commandTable(): string {
  return emitList("commands", COMMANDS, ["command", "summary"]);
}

/** Full tool reference for `crswd-axi --help`. */
export function rootHelpText(): string {
  const flags = emitList(
    "flags",
    [
      { flag: "--help", default: "", description: "show help for any command" },
      { flag: "--version", default: "", description: "print the tool version" },
    ],
    ["flag", "default", "description"],
  );
  const settings = emitList(
    "settings",
    [
      { name: "CRSWD_HOST", default: "http://127.0.0.1:8765", description: "the daemon to sign for" },
      { name: "CRSWD_OP_ITEM", default: "op://Lobster/crswd", description: "1Password item holding the secret" },
      { name: "CRSWD_SHARED_SECRET", default: "", description: "the HMAC secret, instead of 1Password" },
      { name: "CRSWD_AXI_TOKENS", default: "~/.local/state/crswd-axi/tokens.jsonl", description: "bearer store; ':'-separated for more than one" },
    ],
    ["name", "default", "description"],
  );
  return [
    `crswd-axi: ${DESCRIPTION}`,
    commandTable(),
    flags,
    settings,
    "examples[3]:",
    "  crswd-axi list",
    '  crswd-axi prompt <id> "run the tests"',
    "  crswd-axi output <id> --tail 40",
  ].join("\n");
}

/** The static SKILL.md: what the tool is for, in zero-install command forms. */
export function renderSkill(): string {
  const frontmatter = [
    "---",
    "name: crswd-axi",
    `description: "${DESCRIPTION.replace(/"/g, "'")}"`,
    "---",
  ].join("\n");
  const body = [
    "# crswd-axi",
    "",
    `${DESCRIPTION} (built against AXI spec ${SPEC_VERSION}).`,
    "",
    "```",
    commandTable(),
    "```",
    "",
    "## The one thing to get right",
    "",
    "crswd puts a session's bearer token in exactly two responses in that",
    "session's whole life: the `create` reply, and the first `list` after the",
    "daemon restarts and re-adopts it. There is no re-issue path. A caller that",
    "lists sessions and drops the `token` field burns that credential",
    "permanently, and the session can then be neither prompted nor closed by",
    "anyone until it expires.",
    "",
    "`crswd-axi list` captures before it renders, every time, so the bearer is",
    "already on record by the time you read the table. Pass no tokens by hand;",
    "`show`, `prompt`, `output` and `close` look them up.",
    "",
    "## Commands",
    "",
    "```sh",
    "npx -y crswd-axi list",
    "npx -y crswd-axi show <id>",
    "npx -y crswd-axi create <name> --work-dir /absolute/path",
    'npx -y crswd-axi prompt <id> "what to type"',
    "npx -y crswd-axi output <id> --tail 40",
    "npx -y crswd-axi close <id>",
    "npx -y crswd-axi doctor",
    "```",
    "",
    "Every command supports `--help`. Exit codes: 0 success, 1 error, 2 usage",
    "error, 5 usable with an optional connector absent. All output is TOON on",
    "stdout, including errors.",
  ].join("\n");
  return [frontmatter, "", body, ""].join("\n");
}
